 */

import { readFileSync } from 'fs'

// Read command line arguments
const args = process.argv.slice(2)
if (args.length !== 1 || !['replay', 'summary'].includes(args[0])) {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

const mode = args[0]

// Read stdin
let input = ''
try {
  input = readFileSync(0, 'utf8')
} catch (e) {
  input = ''
}

// Parser state
const buckets = new Map() // name -> { capacity, refill, per }
const windows = new Map() // name -> { limit, span }
const routes = new Map() // prefix -> [policy names]
const events = []
let firstEventLine = null
let lastTick = -1

// Helper to check if a string is valid name/prefix/key
function isValidIdentifier(s) {
  return /^[A-Za-z0-9_./:_-]+$/.test(s)
}

// Helper to parse integer
function parseInteger(s, fieldName, minValue, lineNum) {
  if (!/^\d+$/.test(s)) {
    process.stderr.write(`error: line ${lineNum}: ${fieldName} must be an integer of at least ${minValue}\n`)
    process.exit(2)
  }
  const num = parseInt(s, 10)
  if (num < minValue) {
    process.stderr.write(`error: line ${lineNum}: ${fieldName} must be an integer of at least ${minValue}\n`)
    process.exit(2)
  }
  return num
}

// Parse the input
const lines = input.split('\n')
for (let lineNum = 1; lineNum <= lines.length; lineNum++) {
  let line = lines[lineNum - 1]

  // Trim the line
  line = line.trim()

  // Skip empty lines and comments
  if (!line || line.startsWith('#')) {
    continue
  }

  // Split on whitespace
  const parts = line.split(/\s+/)
  const directive = parts[0]

  if (directive === 'bucket') {
    // bucket <name> <capacity> <refill> <per>
    if (firstEventLine !== null) {
      process.stderr.write(`error: line ${lineNum}: declarations must come before the first event\n`)
      process.exit(2)
    }

    if (parts.length !== 5) {
      process.stderr.write(`error: line ${lineNum}: expected bucket <name> <capacity> <refill> <per>\n`)
      process.exit(2)
    }

    const name = parts[1]
    if (!isValidIdentifier(name)) {
      process.stderr.write(`error: line ${lineNum}: invalid policy name ${name}\n`)
      process.exit(2)
    }

    if (buckets.has(name) || windows.has(name)) {
      process.stderr.write(`error: line ${lineNum}: policy ${name} is declared twice\n`)
      process.exit(2)
    }

    const capacity = parseInteger(parts[2], 'capacity', 1, lineNum)
    const refill = parseInteger(parts[3], 'refill', 0, lineNum)
    const per = parseInteger(parts[4], 'per', 1, lineNum)

    buckets.set(name, { capacity, refill, per })
  } else if (directive === 'window') {
    // window <name> <limit> <span>
    if (firstEventLine !== null) {
      process.stderr.write(`error: line ${lineNum}: declarations must come before the first event\n`)
      process.exit(2)
    }

    if (parts.length !== 4) {
      process.stderr.write(`error: line ${lineNum}: expected window <name> <limit> <span>\n`)
      process.exit(2)
    }

    const name = parts[1]
    if (!isValidIdentifier(name)) {
      process.stderr.write(`error: line ${lineNum}: invalid policy name ${name}\n`)
      process.exit(2)
    }

    if (buckets.has(name) || windows.has(name)) {
      process.stderr.write(`error: line ${lineNum}: policy ${name} is declared twice\n`)
      process.exit(2)
    }

    const limit = parseInteger(parts[2], 'limit', 0, lineNum)
    const span = parseInteger(parts[3], 'span', 1, lineNum)

    windows.set(name, { limit, span })
  } else if (directive === 'route') {
    // route <prefix> <policy>...
    if (firstEventLine !== null) {
      process.stderr.write(`error: line ${lineNum}: declarations must come before the first event\n`)
      process.exit(2)
    }

    if (parts.length < 3) {
      process.stderr.write(`error: line ${lineNum}: expected route <prefix> <policy>...\n`)
      process.exit(2)
    }

    const prefix = parts[1]
    if (!isValidIdentifier(prefix)) {
      process.stderr.write(`error: line ${lineNum}: invalid route prefix ${prefix}\n`)
      process.exit(2)
    }

    if (routes.has(prefix)) {
      process.stderr.write(`error: line ${lineNum}: prefix ${prefix} is routed twice\n`)
      process.exit(2)
    }

    const policyNames = parts.slice(2)
    for (const policyName of policyNames) {
      if (!buckets.has(policyName) && !windows.has(policyName)) {
        process.stderr.write(`error: line ${lineNum}: unknown policy ${policyName}\n`)
        process.exit(2)
      }
    }

    routes.set(prefix, policyNames)
  } else if (directive === 'event') {
    // event <tick> <key>
    if (firstEventLine === null) {
      firstEventLine = lineNum
    }

    if (parts.length !== 3) {
      process.stderr.write(`error: line ${lineNum}: expected event <tick> <key>\n`)
      process.exit(2)
    }

    const tick = parseInteger(parts[1], 'tick', 0, lineNum)
    if (tick < lastTick) {
      process.stderr.write(`error: line ${lineNum}: tick ${tick} is before tick ${lastTick}\n`)
      process.exit(2)
    }
    lastTick = tick

    const key = parts[2]
    if (!isValidIdentifier(key)) {
      process.stderr.write(`error: line ${lineNum}: invalid key ${key}\n`)
      process.exit(2)
    }

    events.push({ tick, key, line: lineNum })
  } else {
    process.stderr.write(`error: line ${lineNum}: unknown directive ${directive}\n`)
    process.exit(2)
  }
}

// Runtime state
const bucketStates = new Map() // policyName -> Map(key -> { tokens, lastTick })
const windowStates = new Map() // policyName -> Map(key -> { ticks, lastTick })

// Initialize states
for (const policyName of buckets.keys()) {
  bucketStates.set(policyName, new Map())
}
for (const policyName of windows.keys()) {
  windowStates.set(policyName, new Map())
}

// Find route for a key
function findRoute(key) {
  let bestPrefix = null
  let bestPolicies = null

  for (const [prefix, policies] of routes) {
    if (key.startsWith(prefix)) {
      if (bestPrefix === null || prefix.length > bestPrefix.length) {
        bestPrefix = prefix
        bestPolicies = policies
      }
    }
  }

  return bestPolicies
}

// Check if a bucket allows a request
function bucketAllow(policyName, key, tick) {
  const state = bucketStates.get(policyName)
  let keyState = state.get(key)

  if (!keyState) {
    // Initialize: start full
    keyState = { tokens: buckets.get(policyName).capacity, lastTick: tick }
    state.set(key, keyState)
  } else {
    // Advance the bucket
    const config = buckets.get(policyName)
    const ticksPassed = tick - keyState.lastTick
    const tokensAdded = (config.refill * ticksPassed) / config.per
    keyState.tokens = Math.min(config.capacity, keyState.tokens + tokensAdded)
    keyState.lastTick = tick
  }

  return keyState.tokens >= 1
}

// Record a bucket request
function bucketRecord(policyName, key, tick) {
  const state = bucketStates.get(policyName)
  const keyState = state.get(key)
  keyState.tokens -= 1
}

// Check if a window allows a request
function windowAllow(policyName, key, tick) {
  const state = windowStates.get(policyName)
  let keyState = state.get(key)

  if (!keyState) {
    // Initialize
    keyState = { ticks: [], lastTick: tick }
    state.set(key, keyState)
  } else {
    // Advance the window
    const config = windows.get(policyName)
    const cutoff = tick - config.span
    keyState.ticks = keyState.ticks.filter(t => t > cutoff)
    keyState.lastTick = tick
  }

  return keyState.ticks.length < windows.get(policyName).limit
}

// Record a window request
function windowRecord(policyName, key, tick) {
  const state = windowStates.get(policyName)
  const keyState = state.get(key)
  keyState.ticks.push(tick)
}

// Process events
const replay = []
const summary = new Map() // key -> { allowed, denied }

for (const event of events) {
  const { tick, key } = event

  const policies = findRoute(key)

  if (!policies) {
    // No route matches, always allowed
    replay.push({ tick, key, allowed: true })
    if (!summary.has(key)) {
      summary.set(key, { allowed: 0, denied: 0 })
    }
    summary.get(key).allowed += 1
  } else {
    // Check all policies
    let firstDeny = null
    let allAllow = true

    // First, advance all policies
    for (const policyName of policies) {
      if (buckets.has(policyName)) {
        bucketAllow(policyName, key, tick)
      } else if (windows.has(policyName)) {
        windowAllow(policyName, key, tick)
      }
    }

    // Then, check all policies
    for (const policyName of policies) {
      let allow = false

      if (buckets.has(policyName)) {
        allow = bucketAllow(policyName, key, tick)
      } else if (windows.has(policyName)) {
        allow = windowAllow(policyName, key, tick)
      }

      if (!allow) {
        firstDeny = policyName
        allAllow = false
        break
      }
    }

    if (allAllow) {
      // Record in all policies
      for (const policyName of policies) {
        if (buckets.has(policyName)) {
          bucketRecord(policyName, key, tick)
        } else if (windows.has(policyName)) {
          windowRecord(policyName, key, tick)
        }
      }
      replay.push({ tick, key, allowed: true })
      if (!summary.has(key)) {
        summary.set(key, { allowed: 0, denied: 0 })
      }
      summary.get(key).allowed += 1
    } else {
      replay.push({ tick, key, allowed: false, denyPolicy: firstDeny })
      if (!summary.has(key)) {
        summary.set(key, { allowed: 0, denied: 0 })
      }
      summary.get(key).denied += 1
    }
  }
}

// Output
if (mode === 'replay') {
  for (const entry of replay) {
    if (entry.allowed) {
      process.stdout.write(`${entry.tick} ${entry.key} allow\n`)
    } else {
      process.stdout.write(`${entry.tick} ${entry.key} deny ${entry.denyPolicy}\n`)
    }
  }
} else if (mode === 'summary') {
  const sortedKeys = Array.from(summary.keys()).sort()
  for (const key of sortedKeys) {
    const s = summary.get(key)
    process.stdout.write(`${key} allowed=${s.allowed} denied=${s.denied}\n`)
  }

  let totalAllowed = 0
  let totalDenied = 0
  for (const s of summary.values()) {
    totalAllowed += s.allowed
    totalDenied += s.denied
  }
  process.stdout.write(`total allowed=${totalAllowed} denied=${totalDenied}\n`)
}

process.exit(0)

