    }
    routes.set(prefix, names)
  } else if (directive === 'event') {
    sawEvent = true
    if (parts.length !== 3) fail(`line ${lineNum}: expected event <tick> <key>`)
    const tick = count(parts[1], 'tick', 0, lineNum)
    if (lastTick !== null && tick < lastTick) {
      fail(`line ${lineNum}: tick ${tick} is before tick ${lastTick}`)
    }
    lastTick = tick
    const key = parts[2]
    if (!TOKEN.test(key)) fail(`line ${lineNum}: invalid key ${key}`)
    events.push({ tick, key })
  } else {
    fail(`line ${lineNum}: unknown directive ${directive}`)
  }
}

const routeList = [...routes.entries()].sort((a, b) => b[0].length - a[0].length)

function routeFor(key) {
  for (const [prefix, names] of routeList) {
    if (key.startsWith(prefix)) return names
  }
  return null
}

/**
 * A bucket keeps its tokens as an exact integer numerator over `per`, so the
 * fractional refill of a partial period is never rounded away.
 */
function advance(policy, key, tick) {
  let state = policy.state.get(key)
  if (state === undefined) {
    state =
      policy.kind === 'bucket'
        ? { tokens: policy.capacity * policy.per, at: tick }
        : { ticks: [], at: tick }
    policy.state.set(key, state)
    if (policy.kind === 'window') trim(policy, state, tick)
    return state
  }
  if (policy.kind === 'bucket') {
    const elapsed = tick - state.at
    if (elapsed > 0n) {
      const cap = policy.capacity * policy.per
      const gained = policy.refill * elapsed
      state.tokens = state.tokens + gained > cap ? cap : state.tokens + gained
    }
    state.at = tick
  } else {
    trim(policy, state, tick)
    state.at = tick
  }
  return state
}

function trim(policy, state, tick) {
  const cutoff = tick - policy.span
  state.ticks = state.ticks.filter((t) => t > cutoff)
}

function allows(policy, state) {
  return policy.kind === 'bucket'
    ? state.tokens >= policy.per
    : BigInt(state.ticks.length) < policy.limit
}

function record(policy, state, tick) {
  if (policy.kind === 'bucket') state.tokens -= policy.per
  else state.ticks.push(tick)
}

const out = []
const perKey = new Map()
let totalAllowed = 0
let totalDenied = 0

for (const { tick, key } of events) {
  const names = routeFor(key)
  let denier = null
  if (names !== null) {
    const pairs = names.map((name) => {
      const policy = policies.get(name)
      return { name, policy, state: advance(policy, key, tick) }
    })
    for (const pair of pairs) {
      if (!allows(pair.policy, pair.state)) {
        denier = pair.name
        break
      }
    }
    if (denier === null) {
      for (const pair of pairs) record(pair.policy, pair.state, tick)
    }
  }

  let tally = perKey.get(key)
  if (tally === undefined) {
    tally = { allowed: 0, denied: 0 }
    perKey.set(key, tally)
  }
  if (denier === null) {
    tally.allowed++
    totalAllowed++
    if (mode === 'replay') out.push(`${tick} ${key} allow\n`)
  } else {
    tally.denied++
    totalDenied++
    if (mode === 'replay') out.push(`${tick} ${key} deny ${denier}\n`)
  }
}

if (mode === 'summary') {
  for (const key of [...perKey.keys()].sort()) {
    const tally = perKey.get(key)
    out.push(`${key} allowed=${tally.allowed} denied=${tally.denied}\n`)
  }
  out.push(`total allowed=${totalAllowed} denied=${totalDenied}\n`)
}

process.stdout.write(out.join(''))
